class Solution { public: vector<int> majorityElement(vector<int>& nums){int first=0,second=1,count1=0,count2=0;for(int value:nums){if(value==first)++count1;else if(value==second)++count2;else if(count1==0){first=value;count1=1;}else if(count2==0){second=value;count2=1;}else{--count1;--count2;}}count1=count2=0;for(int value:nums){if(value==first)++count1;else if(value==second)++count2;}vector<int> answer;if(count1>(int)nums.size()/3)answer.push_back(first);if(count2>(int)nums.size()/3)answer.push_back(second);sort(answer.begin(),answer.end());return answer;} };
